DROP TABLE IF EXISTS `ac_item_transaksi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ac_item_transaksi` (
  `itr_id` varchar(70) NOT NULL,
  `itr_transaksi` varchar(60) DEFAULT NULL,
  `itr_item` varchar(40) DEFAULT NULL,
  `itr_qty` bigint DEFAULT NULL,
  `itr_keterangan` longtext,
  `itr_created` datetime(3) DEFAULT NULL,
  `itr_lastupdate` datetime(3) DEFAULT NULL,
  `itr_userupdate` varchar(50) DEFAULT NULL,
  `itr_userupdate_type` longtext,
  PRIMARY KEY (`itr_id`),
  KEY `fk_ac_item_transaksi_master_item` (`itr_item`),
  KEY `fk_ac_transaksi_items` (`itr_transaksi`),
  CONSTRAINT `fk_ac_item_transaksi_master_item` FOREIGN KEY (`itr_item`) REFERENCES `ac_item` (`it_id`),
  CONSTRAINT `fk_ac_transaksi_items` FOREIGN KEY (`itr_transaksi`) REFERENCES `ac_transaksi` (`tr_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

