CREATE TABLE `ac_jenis_produk` (
  `jp_id` varchar(40) NOT NULL,
  `jp_layanan` varchar(30) DEFAULT NULL,
  `jp_nama` longtext,
  `jp_harga` double DEFAULT NULL,
  `jp_satuan` longtext,
  `jp_durasi` bigint DEFAULT NULL,
  `jp_durasi_satuan` longtext,
  `jp_gambar` longtext,
  `jp_lastupdate` datetime(3) DEFAULT NULL,
  `jp_userupdate` varchar(50) DEFAULT NULL,
  `jp_userupdate_type` longtext,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`jp_id`),
  KEY `fk_ac_layanan_products` (`jp_layanan`),
  KEY `idx_ac_jenis_produk_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_ac_layanan_products` FOREIGN KEY (`jp_layanan`) REFERENCES `ac_layanan` (`ly_id`)
